        ),
    )

    add(
        "p7_multi_key_nulls_directions",
        "SELECT id, n, s FROM input "
        "ORDER BY n DESC NULLS FIRST, s ASC NULLS LAST, id LIMIT 40",
        lambda: project(
            stable_sort(
                t_rows,
                [
                    order_key(c("n"), descending=True, nulls_first=True),
                    order_key(c("s"), descending=False, nulls_first=False),
