        t_map,
    )
    add(
        "p8_arith_unary_neg_division_cases",
        "SELECT id, -big AS neg, id / 2 AS half, "
        "CASE WHEN flag THEN TRUE WHEN n > 0 THEN FALSE ELSE flag END AS bc, "
        "CASE WHEN n IS NULL THEN s WHEN n >= 0 THEN '正' ELSE s END AS cs "
