    )

    add(
        "p9_non_pushdown_arithmetic_predicate",
        "SELECT id, n, f FROM input "
        "WHERE f * 2.0 > 1.0 AND n IS NOT NULL AND zflag IS NOT NULL "
        "ORDER BY f DESC, id LIMIT 30",
        lambda: project(
            stable_sort(
                filter_rows(
                    t_rows,
                    And(
                        And(
                            Cmp(
                                ">",
                                Bin("*", c("f"), lit_float(2.0)),
                                lit_float(1.0),
                            ),
                            IsNull(c("n"), negate=True),
                        ),
                        IsNull(c("zflag"), negate=True),
                    ),
                ),
                [order_key(c("f"), descending=True), order_key(c("id"))],
            )[:30],
            [("id", c("id")), ("n", c("n")), ("f", c("f"))],
        ),
    )

    p10_case = Case(
        [
            (Cmp(">", c("n"), lit_int(5)), Lit("big", "utf8")),
            (Cmp("<", c("n"), lit_int(-5)), Lit("small", "utf8")),
        ],
        None,
        t_map,
    )
    add(
        "p10_case_without_else",
        "SELECT id, n, CASE WHEN n > 5 THEN 'big' WHEN n < -5 THEN 'small' END "
        "AS bucket FROM input WHERE id < 40 ORDER BY id",
        lambda: project(
            stable_sort(
                filter_rows(t_rows, Cmp("<", c("id"), lit_int(40))),
                [order_key(c("id"))],
            ),
            [("id", c("id")), ("n", c("n")), ("bucket", p10_case)],
        ),
    )

    p11_bool_case = Case(
        [(IsNull(c("s")), c("flag"))],
        c("zflag"),
        t_map,
    )
    add(
        "p11_boolean_case_in_where",
        "SELECT id, flag, zflag FROM input "
        "WHERE (CASE WHEN s IS NULL THEN flag ELSE zflag END) = TRUE ORDER BY id LIMIT 30",
        lambda: project(
            stable_sort(
                filter_rows(t_rows, Cmp("=", p11_bool_case, Lit(True, "bool"))),
                [order_key(c("id"))],
            )[:30],
            [("id", c("id")), ("flag", c("flag")), ("zflag", c("zflag"))],
        ),
    )

    # -- SELECT DISTINCT ---------------------------------------------------

    def distinct_pipeline(predicate, outputs, type_names, order_keys, limit):
        rows = filter_rows(t_rows, predicate)
        _schema, projected = project(rows, outputs)
        deduped = distinct_rows(projected, type_names)
        if order_keys is not None:
            wrapped = [dict(zip((n for n, _e in outputs), row)) for row in deduped]
            wrapped = stable_sort(wrapped, order_keys)
            deduped = [tuple(row[name] for name, _e in outputs) for row in wrapped]
        if limit is not None:
            deduped = deduped[:limit]
        return _schema, deduped

    add(
        "d1_distinct_first_occurrence_order",
        "SELECT DISTINCT n, flag FROM input WHERE id >= 8",
        lambda: distinct_pipeline(
            Cmp(">=", c("id"), lit_int(8)),
