# HAVING predicates operate on group-context rows (key columns + agg labels).


class _GVal(Val):
    def __init__(self, label: str):
        self.label = label
        self.type = "int64" if label.startswith("COUNT") else "float64"
        self.nullable = not label.startswith("COUNT")

    def eval(self, row):
        return row[self.label]


def _GCmp(op: str, label: str, value: int) -> P:
    return Cmp(op, _GVal(label), Lit(value, "int64"))


class _GIsNull(P):
    def __init__(self, label: str, negate: bool):
        self.label = label
        self.negate = negate

    def eval(self, row):
        result = row[self.label] is None
        return (not result) if self.negate else result


def _gorder(label: str, *, descending=False, nulls_first=False):
    return (lambda context: context[label], descending, nulls_first)


