    def joined(*kinds_and_keys):
        rows, combined = t_rows, dict(t_map)
        current = u_rows
        current_map = dict(u_map)
        # Step list consumed in order: (kind, prior, new, lkey, rkey, right_rows, right_map)
        for kind, lkey, rkey, right_rows, right_map, right_label in kinds_and_keys:
            rows, combined = join_step(
                rows, right_rows, combined, right_map, lkey, rkey, kind
            )
        return rows, combined

    tu_inner = [("inner", "t.n", "u.k", u_rows, u_map, "u")]
    tu_left = [("left", "t.n", "u.k", u_rows, u_map, "u")]
    tu_right = [("right", "t.n", "u.k", u_rows, u_map, "u")]
    tu_full = [("full", "t.n", "u.k", u_rows, u_map, "u")]
    chain_inner = tu_inner + [
        ("inner", "u.k", "w.wk", w_rows, w_map, "w")
    ]
    chain_left_inner = tu_left + [
        ("inner", "u.k", "w.wk", w_rows, w_map, "w")
    ]
    chain_inner_right = tu_inner + [
        ("right", "u.k", "w.wk", w_rows, w_map, "w")
    ]

    def maps_for(steps):
        combined = dict(t_map)
        for _kind, _lk, _rk, _rr, right_map, _label in steps:
            combined.update(right_map)
        # Nullability derivation must follow the actual step kinds.
        derived = dict(t_map)
        left_rows = t_rows
        for kind, _lk, _rk, _rr, right_map, _label in steps:
            pad_left = kind in ("right", "full")
            pad_right = kind in ("left", "full")
            derived = {
                name: (ty, True if pad_left else nu) for name, (ty, nu) in derived.items()
            }
            derived.update(
                {
                    name: (ty, True if pad_right else nu)
                    for name, (ty, nu) in right_map.items()
                }
            )
        return derived

