    def join_distinct(steps, predicate, outputs_names, type_names, order_keys, limit):
        rows = filter_rows(joined(*steps)[0], predicate)
        outputs = [(name, cc(maps_for(steps), name)) for name in outputs_names]
        _schema, projected = project(rows, outputs)
        deduped = distinct_rows(projected, type_names)
        if order_keys is not None:
            wrapped = [dict(zip(outputs_names, row)) for row in deduped]
            wrapped = stable_sort(wrapped, order_keys)
            deduped = [tuple(row[name] for name in outputs_names) for row in wrapped]
        if limit is not None:
            deduped = deduped[:limit]
        return _schema, deduped

