    )

    return scenarios


# ---------------------------------------------------------------------------
# Layout variants and file writing through the public entries
# ---------------------------------------------------------------------------


COMPRESSIONS = ("none", "zlib")
DICT_CHOICES = (False, True)
V2_GROUP_SIZES = (1, 3, 7, 64)


def _label(kind, group_size, compression, dictionary):
    if kind == "v1":
        return f"v1_{compression}_{'dict' if dictionary else 'plain'}"
    return f"v2r{group_size}_{compression}_{'dict' if dictionary else 'plain'}"


def _write_variant(path, table, kind, group_size, compression, dictionary, dict_columns):
    if kind == "v1":
        write_file(
            path,
            table,
            compression=compression,
            dictionary_encoding=dict_columns if dictionary else (),
        )
    else:
        write_partitioned_file(
            path,
            table,
            group_size,
            compression=compression,
            dictionary_encoding=dict_columns if dictionary else (),
        )


@pytest.fixture(scope="module")
def datasets():
    return {"t": build_t(), "u": build_u(), "w": build_w()}


@pytest.fixture()
def layouts(tmp_path, datasets):
    """Write every t layout variant plus a fixed variant set for u and w."""
    tables = {
        "t": Table(T_SCHEMA, datasets["t"]),
        "u": Table(U_SCHEMA, datasets["u"]),
        "w": Table(W_SCHEMA, datasets["w"]),
    }
    dict_columns = {"t": ["s", "znull"], "u": ["tag"], "w": ["wtag"]}

    t_variants = {}
    for compression in COMPRESSIONS:
        for dictionary in DICT_CHOICES:
            label = _label("v1", None, compression, dictionary)
            path = tmp_path / f"t_{label}.caef"
            _write_variant(
                path, tables["t"], "v1", None, compression, dictionary,
                dict_columns["t"],
            )
            t_variants[label] = path
    for group_size in V2_GROUP_SIZES:
        for compression in COMPRESSIONS:
            for dictionary in DICT_CHOICES:
                label = _label("v2", group_size, compression, dictionary)
                path = tmp_path / f"t_{label}.caef"
                _write_variant(
                    path, tables["t"], "v2", group_size, compression, dictionary,
                    dict_columns["t"],
                )
                t_variants[label] = path

    partner_variants = {}
    partner_specs = {
        "u": [
            ("v1", None, "none", False),
            ("v1", None, "zlib", True),
            ("v2", 5, "none", False),
