        blobs = {}
        row_counts = {}
        variants = sorted(layouts["t"])
        for variant in variants:
            destination = tmp_path / f"{scenario['name']}_{variant}.{fmt}"
            count = export_query_file(
                layouts["t"][variant], scenario["sql"], destination, fmt
            )
            # Repeat once more: identical input + SQL + format must restay byte-stable.
            again = tmp_path / f"{scenario['name']}_{variant}_again.{fmt}"
            assert export_query_file(
                layouts["t"][variant], scenario["sql"], again, fmt
            ) == count
            assert again.read_bytes() == destination.read_bytes()
            blobs[variant] = destination.read_bytes()
            row_counts[variant] = count
        baseline = blobs[variants[0]]
        for variant in variants[1:]:
