            lines = baseline.decode("utf-8").splitlines()
            assert len(lines) == len(expected_rows)
            for line, exp_row in zip(lines, expected_rows):
                obj = json.loads(line)
                assert list(obj) == [name for name, _t, _n in expected_schema]
                assert tuple(obj[name] for name, _t, _n in expected_schema) == exp_row
        else:
            header = baseline.decode("utf-8").splitlines()[0]
