def build_join_scenarios(datasets) -> list:
    t_rows = qualify(scan(datasets["t"]), "t")
    u_rows = qualify(scan(datasets["u"]), "u")
    w_rows = qualify(scan(datasets["w"]), "w")
    t_map = schema_for(T_SCHEMA, "t")
    u_map = schema_for(U_SCHEMA, "u")
    w_map = schema_for(W_SCHEMA, "w")
    scenarios = []

    def add(name, sql, expected, *, ordered=True):
        scenarios.append({"name": name, "sql": sql, "expected": expected, "ordered": ordered})

    def joined(*kinds_and_keys):
        rows, combined = t_rows, dict(t_map)
        current = u_rows
        current_map = dict(u_map)
        # Step list consumed in order: (kind, prior, new, lkey, rkey, right_rows, right_map)
        for kind, lkey, rkey, right_rows, right_map, right_label in kinds_and_keys:
            rows, combined = join_step(
                rows, right_rows, combined, right_map, lkey, rkey, kind
            )
        return rows, combined

    tu_inner = [("inner", "t.n", "u.k", u_rows, u_map, "u")]
    tu_left = [("left", "t.n", "u.k", u_rows, u_map, "u")]
    tu_right = [("right", "t.n", "u.k", u_rows, u_map, "u")]
    tu_full = [("full", "t.n", "u.k", u_rows, u_map, "u")]
    chain_inner = tu_inner + [
        ("inner", "u.k", "w.wk", w_rows, w_map, "w")
    ]
    chain_left_inner = tu_left + [
        ("inner", "u.k", "w.wk", w_rows, w_map, "w")
    ]
    chain_inner_right = tu_inner + [
        ("right", "u.k", "w.wk", w_rows, w_map, "w")
    ]

    def maps_for(steps):
        combined = dict(t_map)
        for _kind, _lk, _rk, _rr, right_map, _label in steps:
            combined.update(right_map)
        # Nullability derivation must follow the actual step kinds.
        derived = dict(t_map)
        left_rows = t_rows
        for kind, _lk, _rk, _rr, right_map, _label in steps:
            pad_left = kind in ("right", "full")
            pad_right = kind in ("left", "full")
            derived = {
                name: (ty, True if pad_left else nu) for name, (ty, nu) in derived.items()
            }
            derived.update(
                {
                    name: (ty, True if pad_right else nu)
                    for name, (ty, nu) in right_map.items()
                }
            )
        return derived

    def cc(map_, name):
        return Col(name, map_)

    add(
        "j1_inner_pushdown_order_limit",
        "SELECT t.id, u.uid, t.n, u.k FROM t INNER JOIN u ON t.n = u.k "
        "WHERE t.id < 55 AND u.uid > 1002 ORDER BY t.id, u.uid LIMIT 40",
        lambda: project(
            stable_sort(
                filter_rows(
                    joined(*tu_inner)[0],
                    And(
                        Cmp("<", cc(maps_for(tu_inner), "t.id"), Lit(55, "int64")),
                        Cmp(">", cc(maps_for(tu_inner), "u.uid"), Lit(1002, "int64")),
                    ),
                ),
                [
                    order_key(cc(maps_for(tu_inner), "t.id")),
                    order_key(cc(maps_for(tu_inner), "u.uid")),
                ],
            )[:40],
            [
                ("t.id", cc(maps_for(tu_inner), "t.id")),
                ("u.uid", cc(maps_for(tu_inner), "u.uid")),
                ("t.n", cc(maps_for(tu_inner), "t.n")),
                ("u.k", cc(maps_for(tu_inner), "u.k")),
            ],
        ),
    )

    left_map = maps_for(tu_left)
    add(
        "j2_left_outer_or_predicate_nulls_first",
        "SELECT t.id, u.uid, t.n, u.tag FROM t LEFT JOIN u ON t.n = u.k "
        "WHERE (u.uid IS NULL OR t.flag = TRUE) AND t.id >= 20 "
        "ORDER BY u.uid NULLS FIRST, t.id NULLS FIRST LIMIT 50",
        lambda: project(
            stable_sort(
                filter_rows(
                    joined(*tu_left)[0],
                    And(
                        Or(
                            IsNull(cc(left_map, "u.uid")),
                            Cmp("=", cc(left_map, "t.flag"), Lit(True, "bool")),
