                        Cmp(">=", cc(left_map, "t.id"), Lit(20, "int64")),
                    ),
                ),
                [
                    order_key(cc(left_map, "u.uid"), nulls_first=True),
                    order_key(cc(left_map, "t.id"), nulls_first=True),
                ],
            )[:50],
            [
                ("t.id", cc(left_map, "t.id")),
                ("u.uid", cc(left_map, "u.uid")),
