        "CASE WHEN n IS NULL THEN s WHEN n >= 0 THEN '正' ELSE s END AS cs "
        "FROM input WHERE id < 32 ORDER BY id",
        lambda: project(
            stable_sort(
                filter_rows(t_rows, Cmp("<", c("id"), li(32))),
